package com.globalhire.controller;import com.globalhire.repository.CountryRepository;import org.springframework.web.bind.annotation.*;import java.util.*;import java.util.stream.*;@RestController @RequestMapping("/api/dashboard")public class DashboardController{final CountryRepository r;public DashboardController(CountryRepository x){r=x;}@GetMapping("/summary")public Map<String,Object> s(){var c=r.findAll();var costs=c.stream().map(x->Map.of("country",x.getName(),"cost",x.getAverageSalary()*(1+x.getEmployerTax()/100+x.getSocialSecurity()/100))).limit(12).toList();return Map.of("countriesAnalyzed",c.size(),"avgHiringCost",c.stream().mapToDouble(x->x.getAverageSalary()*(1+x.getEmployerTax()/100+x.getSocialSecurity()/100)).average().orElse(0),"avgHiringTime",30,"avgRetention",.78,"avgAcceptance",.74,"complianceAlerts",c.stream().filter(x->x.isVisaRequirement()||x.isSponsorship()).count(),"countryCosts",costs);}}